/// Admin panel: publish new journeys and view sales / user / invoice reports.
class EnlistFlightScreen extends StatelessWidget {
  const EnlistFlightScreen({super.key});
  @override Widget build(BuildContext context) => AppShell(title: 'Partner dashboard', child: DefaultTabController(length: 2, child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
    const Text('PARTNER DASHBOARD', style: TextStyle(color: blue, fontSize: 12, fontWeight: FontWeight.w800, letterSpacing: 1.2)), const SizedBox(height: 10),
    Container(decoration: BoxDecoration(color: Colors.white, borderRadius: BorderRadius.circular(12), border: Border.all(color: line)), child: const TabBar(labelColor: navy, unselectedLabelColor: muted, indicatorColor: blue, indicatorWeight: 3, dividerColor: Colors.transparent, labelStyle: TextStyle(fontWeight: FontWeight.w800), tabs: [Tab(icon: Icon(Icons.publish_rounded), text: 'Publish journey'), Tab(icon: Icon(Icons.insights_rounded), text: 'Reports')])), const SizedBox(height: 20),
    const Expanded(child: TabBarView(children: [_PublishForm(), ReportsView()])),
  ])));
}

class _PublishForm extends StatefulWidget { const _PublishForm(); @override State<_PublishForm> createState() => _PublishFormState(); }
class _PublishFormState extends State<_PublishForm> with AutomaticKeepAliveClientMixin { // keep-alive: a half-filled form survives a visit to Reports
  @override bool get wantKeepAlive => true;
  final formKey = GlobalKey<FormState>(); final number = TextEditingController(text: 'AF '); final airline = TextEditingController(text: 'AeroFlow Airways');
  final counts = {for (final c in TravelClass.values) c: TextEditingController(text: c == TravelClass.first ? '8' : c == TravelClass.business ? '20' : '60')};
  final prices = {for (final c in TravelClass.values) c: TextEditingController(text: c == TravelClass.first ? '24000' : c == TravelClass.business ? '12500' : '6200')};
  Airport? origin; Airport? destination; DateTime departure = DateTime.now().add(const Duration(days: 1, hours: 2)); DateTime arrival = DateTime.now().add(const Duration(days: 1, hours: 4));
  @override void dispose() { number.dispose(); airline.dispose(); for (final c in counts.values) { c.dispose(); } for (final c in prices.values) { c.dispose(); } super.dispose(); }
  @override Widget build(BuildContext context) { super.build(context); final airports = context.watch<FlightController>().airports; return Form(key: formKey, child: ListView(children: [const Text('Publish a new journey', style: TextStyle(fontSize: 30, fontWeight: FontWeight.w800)), const SizedBox(height: 8), const Text('Create a listing travellers can search and book immediately.', style: TextStyle(color: muted)), const SizedBox(height: 24), _section('Flight details', Wrap(spacing: 16, runSpacing: 16, children: [_text(number, 'Flight number'), _text(airline, 'Airline name'), _airport('Origin airport', origin, airports, (v) => setState(() => origin = v)), _airport('Destination airport', destination, airports, (v) => setState(() => destination = v)), _date('Departure', departure, (v) => setState(() => departure = v)), _date('Arrival', arrival, (v) => setState(() => arrival = v))])), const SizedBox(height: 20), _section('Cabin configuration', Column(crossAxisAlignment: CrossAxisAlignment.start, children: [const Text('First and Business are laid out 2-2 (A C | D F); Economy is 3-3 (A B C | D E F). A/F are window seats, C/D are aisle seats.', style: TextStyle(color: muted, fontSize: 13)), const SizedBox(height: 16), ...TravelClass.values.map((c) => Padding(padding: const EdgeInsets.only(bottom: 12), child: Row(children: [SizedBox(width: 130, child: Text(c.label, style: const TextStyle(fontWeight: FontWeight.bold))), Expanded(child: TextFormField(controller: counts[c], keyboardType: TextInputType.number, decoration: const InputDecoration(labelText: 'Seat count'), validator: _numberValidator)), const SizedBox(width: 14), Expanded(child: TextFormField(controller: prices[c], keyboardType: TextInputType.number, decoration: const InputDecoration(labelText: 'Price per seat (₹)'), validator: _numberValidator))])))])), const SizedBox(height: 24), Align(alignment: Alignment.centerRight, child: FilledButton.icon(onPressed: _publish, icon: const Icon(Icons.publish), label: const Padding(padding: EdgeInsets.symmetric(vertical: 12), child: Text('Publish journey'))))])); }
  Widget _section(String title, Widget content) => Panel(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text(title, style: const TextStyle(fontSize: 18, fontWeight: FontWeight.w800)), const SizedBox(height: 18), content]));
  Widget _text(TextEditingController c, String label) => SizedBox(width: 260, child: TextFormField(controller: c, decoration: InputDecoration(labelText: label), validator: (v) => v == null || v.trim().isEmpty ? 'Required' : null));
  Widget _airport(String label, Airport? value, List<Airport> airports, ValueChanged<Airport?> changed) => SizedBox(width: 260, child: AirportField(label: label, value: value, airports: airports, onChanged: changed, required: true));
  Widget _date(String label, DateTime value, ValueChanged<DateTime> changed) => SizedBox(width: 260, child: OutlinedButton.icon(onPressed: () async { final d = await showDatePicker(context: context, initialDate: value, firstDate: DateTime.now(), lastDate: DateTime.now().add(const Duration(days: 730))); if (d != null && mounted) { final t = await showTimePicker(context: context, initialTime: TimeOfDay.fromDateTime(value)); if (t != null) changed(DateTime(d.year, d.month, d.day, t.hour, t.minute)); } }, icon: const Icon(Icons.schedule), label: Text('$label\n${value.day}/${value.month}/${value.year} ${TimeOfDay.fromDateTime(value).format(context)}')));
  String? _numberValidator(String? value) => (double.tryParse(value ?? '') ?? 0) <= 0 ? 'Enter a positive value' : null;
  Future<void> _publish() async { if (!(formKey.currentState?.validate() ?? false) || origin == null || destination == null) return; if (origin!.code == destination!.code || !arrival.isAfter(departure)) { ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Choose different airports and an arrival after departure.'))); return; } final controller = context.read<FlightController>(); try { await controller.publishFlight(number: number.text.trim(), airline: airline.text.trim(), origin: origin!, destination: destination!, departure: departure, arrival: arrival, counts: {for (final c in TravelClass.values) c: int.parse(counts[c]!.text)}, prices: {for (final c in TravelClass.values) c: double.parse(prices[c]!.text)}); if (!mounted) return; ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Journey published and ready for discovery.'))); Navigator.pushNamedAndRemoveUntil(context, '/', (_) => false); } catch (e) { if (!mounted) return; ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(e.toString().replaceFirst('Exception: ', '')))); } }
}
